// Long-hover hints (2026-11-10): the cursor on a panel control for 10 s -> a short line scrolls in the readout.
// One line per control, in plain words. PROJECT > SYSTEM > HOVER HINTS turns them on and off (hints.cfg).
#pragma once
static const char *const hint_sm[P_TYPE] = {
    "", "TUNES THE SAMPLE IN SEMITONES", "FINE TUNING IN CENTS", "HOW LOUD THE PAD PLAYS", "LEFT OR RIGHT IN THE STEREO",
    "WHERE PLAYBACK STARTS IN THE FILE", "WHERE PLAYBACK ENDS", "FORWARD OR BACKWARD (REVERSE)",
    "GATE: STOPS WHEN THE STEP ENDS. POLY: NOTES RING OVER EACH OTHER", "THE NOTE THE SAMPLE IS IN: AUTO FINDS IT, DRUMS DO NOT TRANSPOSE",
    "HOW MANY SLICES: EACH STEP CAN PLAY ONE. EDIT ON THE PICTURE OPENS THE SLICE EDITOR", "STRETCHES THE SAMPLE TO THE TEMPO: BEATS FOR DRUMS, TONES FOR MELODY",
    "HOW MANY BARS THE LOOP LASTS", "THE LOOP'S OWN TEMPO: EDIT TAPS IT IN TIME, OPT+EDIT GIVES AUTO BACK", "GRAIN LENGTH FOR TONES AND TEXTURE", "RANDOM JITTER OF THE GRAINS",
};
static const char *const hint_ac[AP_N] = {
    "SAW OR SQUARE: THE BASIC TONE", "TUNES THE WHOLE BASS", "FILTER CUTOFF: THE MAIN SQUELCH KNOB", "RESONANCE: MORE = MORE ACID",
    "HOW FAR EACH NOTE OPENS THE FILTER", "HOW FAST THE FILTER CLOSES AFTER A NOTE", "HOW HARD ACCENTED STEPS HIT",
    "DISTORTION KIND", "DISTORTION AMOUNT", "DISTORTION BRIGHTNESS", "DRY / DISTORTED BALANCE",
};
static const char *const hint_cl[CP_N] = {
    "WHERE IN THE SAMPLE THE GRAINS ARE TAKEN", "HOW FAR GRAINS WANDER AROUND THE POSITION", "LENGTH OF EACH GRAIN",
    "HOW MANY GRAINS PLAY AT ONCE", "ADDS GRAINS AN OCTAVE OR A FIFTH UP", "MOVES THE POSITION ALONG BY ITSELF, IN BARS",
};
static const char *const hint_cx[CX_N] = {
    "GRAIN LENGTHS VARY AT RANDOM", "THE SHAPE OF EACH GRAIN'S FADE", "SHARE OF GRAINS PLAYED BACKWARD", "GRAIN PITCH IN SEMITONES",
    "GRAIN PITCH IN CENTS", "RANDOM PITCH PER GRAIN", "WHICH INTERVALS RANDOM PITCH PICKS", "GRAINS ON THE TEMPO GRID OR FREE",
    "RANDOM TIMING OF GRAINS", "STEREO SPREAD OF THE GRAINS", "DIRECTION THE POSITION MOVES", "HOLDS THE POSITION STILL",
    "FADE IN OF THE CLOUD", "FADE OUT OF THE CLOUD", "DARKER OR BRIGHTER",
};
static const char *const hint_ax[AX_N] = {
    "A SUB OSCILLATOR UNDER THE BASS", "SUB ONE OR TWO OCTAVES DOWN", "SUB WAVE SHAPE", "PULSE WIDTH OF THE SQUARE WAVE",
    "ADDS NOISE TO THE TONE", "VOLUME ATTACK: SOFTER STARTS", "VOLUME RELEASE: NOTES RING ON", "SLIDE TIME BETWEEN SLID STEPS",
    "HOW FAR THE FILTER ENVELOPE CAN REACH", "FILTER FOLLOWS THE NOTE PITCH", "HIGH-PASS INSIDE THE RESONANCE: A THINNER PEAK",
    "KEEPS THE LOW END WHEN RESONANCE IS HIGH", "ACCENT ENVELOPE ATTACK", "ACCENT ENVELOPE DECAY", "SOFT CLIPPING OF THE OUTPUT",
};
static const char *wv_hint(int k) {      // WAVE (2026-11-25): what a parameter does, by its kind
    int o = k < WP_SUB_LEVEL ? k & 15 : -1, e = k >= WP_ENV1 && k < WP_LFO1 ? (k - WP_ENV1) % WE_N : -1, l = k >= WP_LFO1 && k < WP_POLY ? (k - WP_LFO1) % WL_N : -1;
    switch (o) {
    case WO_ON: return "THE OSCILLATOR ON OR OFF"; case WO_TABLE: return "THE WAVETABLE: EDIT ON THE PICTURE BROWSES (BUILT-IN, THEN WAVETABLES/)";
    case WO_POS: return "WHERE IN THE TABLE: MOVES THROUGH ITS FRAMES, THE SOUND MORPHS"; case WO_OCT: return "OCTAVES UP OR DOWN";
    case WO_SEMI: return "SEMITONES UP OR DOWN"; case WO_FINE: return "CENTS: A SMALL DETUNE AGAINST THE OTHER OSCILLATOR"; case WO_LEVEL: return "HOW LOUD THIS OSCILLATOR IS";
    case WO_PAN: return "LEFT OR RIGHT"; case WO_PHASE: return "WHERE IN THE CYCLE EACH NOTE STARTS"; case WO_RAND: return "A RANDOM START PER VOICE: LESS CLICK, MORE LIFE";
    case WO_UNI: return "UNISON: COPIES OF THE OSCILLATOR, DETUNED (CPU: KEEP IT LOW ON BIG CHORDS)"; case WO_DET: return "HOW FAR THE UNISON COPIES SPREAD IN PITCH";
    case WO_WIDTH: return "HOW WIDE THE UNISON COPIES SPREAD IN STEREO"; case WO_WARP: return "BENDS HOW THE TABLE IS READ: SYNC, BEND, PWM, ASYM, FLIP, MIRROR, QUANT, FM, AM, RM";
    case WO_WAMT: return "HOW MUCH THE WARP DOES"; }
    if (e >= 0) { static const char *const eh[WE_N] = {"RISE TIME", "TIME TO FALL TO THE SUSTAIN LEVEL", "LEVEL WHILE THE NOTE IS HELD", "FADE AFTER THE NOTE IS LET GO", "> 0 FAST START (LIKE AN RC), < 0 SLOW START"};
        return k < WP_ENV2 ? (e == WE_ATT ? "ENV1 IS THE VOLUME: RISE TIME" : eh[e]) : k < WP_ENV3 ? (e == WE_ATT ? "ENV2 MOVES THE FILTER (ENV AMT): RISE TIME" : eh[e]) : (e == WE_ATT ? "ENV3: FOR THE MATRIX ONLY. RISE TIME" : eh[e]); }
    if (l >= 0) { static const char *const lh[WL_N] = {"THE LFO'S WAVE: S&H = RANDOM STEPS", "LFO SPEED (A DIVISION WHEN SYNCED)", "FREE, OR TIED TO THE TEMPO", "FREE: VOICES SHARE IT. RETRIG: FROM 0 EACH NOTE. ONE: ONE CYCLE, THEN IT HOLDS", "WHERE THE LFO STARTS"};
        return lh[l]; }
    switch (k) {
    case WP_SUB_LEVEL: return "A SIMPLE OSCILLATOR ONE OR TWO OCTAVES DOWN"; case WP_SUB_SHAPE: return "THE SUB'S WAVE"; case WP_SUB_OCT: return "ONE OR TWO OCTAVES BELOW THE NOTE";
    case WP_SUB_PAN: return "THE SUB LEFT OR RIGHT"; case WP_SUB_DIRECT: case WP_NOISE_DIRECT: return "ON: PAST THE FILTER, UNTOUCHED BY IT";
    case WP_NOISE_LEVEL: return "ADDS NOISE: BREATH, HISS, PERCUSSION"; case WP_NOISE_TYPE: return "WHITE: BRIGHT. PINK: SOFTER, DARKER";
    case WP_F_TYPE: return "LP12 LP24 LOW-PASS, HP12 HIGH-PASS, BP BAND, NOTCH, LADDER: THE CLASSIC 4-POLE";
    case WP_F_CUT: return "THE FILTER'S FREQUENCY: LOWER = DARKER (LOW-PASS)"; case WP_F_RES: return "A PEAK AT THE CUTOFF: MORE = A WHISTLE";
    case WP_F_DRIVE: return "PUSHES THE SOUND INTO THE FILTER: WARMER, THEN DIRTY"; case WP_F_KEY: return "THE CUTOFF FOLLOWS THE NOTE: 100 = ONE OCTAVE PER OCTAVE";
    case WP_F_ENV: return "HOW FAR ENV2 OPENS (OR CLOSES) THE FILTER";
    case WP_POLY: return "HOW MANY NOTES AT ONCE: 1 = MONO"; case WP_LEGATO: return "MONO: A NOTE HELD OVER THE LAST ONE SLIDES, NO NEW ATTACK";
    case WP_GLIDE: return "SLIDE FROM THE LAST NOTE TO THE NEW ONE"; case WP_BEND: return "PITCH WHEEL RANGE IN SEMITONES"; case WP_VELSENS: return "HOW MUCH HOW HARD YOU PLAY SETS THE LEVEL";
    case WP_MASTER: return "THE SOUND'S OWN LEVEL"; case WP_QUALITY: return "ECO: LIGHT ON THE CPU. HIGH: SMOOTHER READS AND FILTER, ABOUT TWICE THE CPU";
    case WP_ARP: return "ARPEGGIATOR: HELD CHORDS PLAY NOTE BY NOTE"; case WP_ARP_MODE: return "ARP ORDER: UP, DOWN, AS PLAYED, UP AND DOWN";
    case WP_ARP_OCT: return "ARP RANGE IN OCTAVES"; case WP_ARP_RATE: return "ARP SPEED ON THE TEMPO"; case WP_ARP_GATE: return "ARP NOTE LENGTH";
    }
    if (k >= WP_MACRO1 && k <= WP_MODWHEEL) return "A SOURCE FOR THE MATRIX: TURN IT, WHAT IT IS ROUTED TO MOVES";
    if (k >= WP_MTX && k < WP_MTX + 64) { static const char *const mh[4] = {"WHAT MOVES: AN ENVELOPE, AN LFO, VELOCITY, THE NOTE, A MACRO", "WHAT IS MOVED: EDIT, THEN POINT AT A CARD", "HOW FAR, EITHER WAY", "UNI: 0..1 FROM THE VALUE. BI: BOTH WAYS AROUND IT"}; return mh[(k - WP_MTX) & 3]; }
    return NULL;
}
static const char *par_hint(int p) {
    if (p > 0 && p < P_TYPE) return hint_sm[p];
    if (p == P_SRC) return "THE SAMPLE THE GRAINS COME FROM: EDIT BROWSES";
    if (p == P_SX + SX_FIN) return "THE SOUND COMES IN OVER THIS TIME INSTEAD OF AT ONCE";
    if (p == P_SX + SX_FOUT) return "THE SOUND FADES OVER THIS TIME BEFORE ITS END, AND WHEN A STEP OR NOTE CUTS IT";
    if (p == P_SX + SX_XFADE) return "A SLICE OR NOTE PLAYS ON THIS LONG PAST ITS END WHILE THE NEXT ONE FADES IN: NO CLICKS BETWEEN SLICES";
    if (p == P_NORM) return "BRINGS A QUIET SAMPLE UP: PEAK BY ITS LOUDEST POINT, LOUD BY ITS AVERAGE LEVEL";
    if (p >= P_AC && p < P_AC + AP_N) return hint_ac[p - P_AC];
    if (p >= P_CL && p < P_CL + CP_N) return hint_cl[p - P_CL];
    if (p >= P_CX && p < P_CX + CX_N) return hint_cx[p - P_CX];
    if (p >= P_AX && p < P_AX + AX_N) return hint_ax[p - P_AX];
    if (p >= P_WV && p < P_WV + WP_N) return wv_hint(p - P_WV);
    if (p == P_SLWAY) return "EQUAL: SAME-SIZE PARTS. TRANSIENTS: A CUT AT EVERY HIT. BY HAND: YOUR OWN POINTS";
    return NULL;
}
